1	#!/usr/bin/env -S deno run --allow-env --allow-net
2	/**
3	 * T8.1: Seed data and disclosure.
4	 *
5	 * Seeds the demo history that no run of real calls produced. The seed carries
6	 * one item ("the dentist") with three call runs on three separate local dates,
7	 * each with an item_mentions row linking the item to the run. Optionally seeds
8	 * two more items with fewer mentions so Today does not look staged.
9	 *
10	 * Usage:
11	 *   deno run --allow-env --allow-net scripts/seed.ts --email <address>
12	 *   deno run --allow-env --allow-net scripts/seed.ts --email <address> --apply
13	 *   deno run --allow-env --allow-net scripts/seed.ts --email <address> --remove
14	 *   deno run --allow-env --allow-net scripts/seed.ts --email <address> --demo-date 2026-09-14
15	 *
16	 * Flags:
17	 *   --email <address>       The account to seed. Must have a profiles row.
18	 *   --demo-date <YYYY-MM-DD> The date the 34 days count to. Defaults to today
19	 *                            in the profile's timezone.
20	 *   --apply                 Write rows. Without this flag, only the plan prints.
21	 *   --remove                Delete every seeded row for the account.
22	 *   --i-confirmed-dry-run   Required for --apply against a non-local URL.
23	 *
24	 * Reaches Supabase only through ORMA_API_URL with SUPABASE_SERVICE_ROLE_KEY,
25	 * because the admin API rejects the new-format secret key.
26	 */
27	
28	import { createClient } from "npm:@supabase/supabase-js@2";
29	
30	// ---------------------------------------------------------------------------
31	// Environment
32	// ---------------------------------------------------------------------------
33	
34	function requireEnv(name: string): string {
35	  const value = Deno.env.get(name);
36	  if (!value) {
37	    console.error(`Missing required environment variable: ${name}`);
38	    Deno.exit(1);
39	  }
40	  return value;
41	}
42	
43	const ORMA_API_URL = requireEnv("ORMA_API_URL").replace(/\/+$/, "");
44	const SERVICE_ROLE_KEY = requireEnv("SUPABASE_SERVICE_ROLE_KEY");
45	
46	// ---------------------------------------------------------------------------
47	// CLI arguments
48	// ---------------------------------------------------------------------------
49	
50	function parseArgs(args: string[]) {
51	  let email: string | undefined;
52	  let demoDate: string | undefined;
53	  let apply = false;
54	  let remove = false;
55	  let confirmedDryRun = false;
56	
57	  for (let i = 0; i < args.length; i++) {
58	    switch (args[i]) {
59	      case "--email":
60	        email = args[++i];
61	        break;
62	      case "--demo-date":
63	        demoDate = args[++i];
64	        break;
65	      case "--apply":
66	        apply = true;
67	        break;
68	      case "--remove":
69	        remove = true;
70	        break;
71	      case "--i-confirmed-dry-run":
72	        confirmedDryRun = true;
73	        break;
74	      default:
75	        console.error(`Unknown flag: ${args[i]}`);
76	        Deno.exit(1);
77	    }
78	  }
79	
80	  if (!email) {
81	    console.error("--email is required.");
82	    Deno.exit(1);
83	  }
84	
85	  if (apply && remove) {
86	    console.error("Cannot pass both --apply and --remove.");
87	    Deno.exit(1);
88	  }
89	
90	  return { email, demoDate, apply, remove, confirmedDryRun };
91	}
92	
93	const flags = parseArgs(Deno.args);
94	
95	// ---------------------------------------------------------------------------
96	// Safety: refuse --apply against non-local without --i-confirmed-dry-run
97	// ---------------------------------------------------------------------------
98	
99	function isLocalUrl(url: string): boolean {
100	  try {
101	    const parsed = new URL(url);
102	    return parsed.hostname === "127.0.0.1" ||
103	      parsed.hostname === "localhost" ||
104	      parsed.hostname === "0.0.0.0" ||
105	      parsed.hostname === "[::1]";
106	  } catch {
107	    return false;
108	  }
109	}
110	
111	if (flags.apply && !isLocalUrl(ORMA_API_URL) && !flags.confirmedDryRun) {
112	  console.error(
113	    "Refusing --apply against a non-local URL without --i-confirmed-dry-run.",
114	  );
115	  console.error(`ORMA_API_URL is ${ORMA_API_URL}`);
116	  Deno.exit(1);
117	}
118	
119	// ---------------------------------------------------------------------------
120	// Supabase client
121	// ---------------------------------------------------------------------------
122	
123	const supabase = createClient(ORMA_API_URL, SERVICE_ROLE_KEY, {
124	  auth: {
125	    persistSession: false,
126	    autoRefreshToken: false,
127	    detectSessionInUrl: false,
128	  },
129	});
130	
131	// ---------------------------------------------------------------------------
132	// Lookup the profile by email (paginates auth.admin.listUsers)
133	// ---------------------------------------------------------------------------
134	
135	async function lookupProfile(email: string) {
136	  let page = 1;
137	  const perPage = 50;
138	  let user: { id: string; email?: string } | undefined;
139	
140	  while (true) {
141	    const { data: userData, error: userError } = await supabase.auth.admin
142	      .listUsers({ page, perPage });
143	    if (userError) {
144	      console.error("Failed to list users:", userError.message);
145	      Deno.exit(1);
146	    }
147	    user = userData.users.find(
148	      (u) => u.email?.toLowerCase() === email.toLowerCase(),
149	    );
150	    if (user) break;
151	    if (userData.users.length < perPage) break;
152	    page++;
153	  }
154	
155	  if (!user) {
156	    console.error(`No auth.users row found for email: ${email}`);
157	    Deno.exit(1);
158	  }
159	
160	  const { data: profile, error: profileError } = await supabase
161	    .from("profiles")
162	    .select("*")
163	    .eq("id", user.id)
164	    .single();
165	  if (profileError || !profile) {
166	    console.error(
167	      `No profiles row found for user ${user.id}:`,
168	      profileError?.message,
169	    );
170	    Deno.exit(1);
171	  }
172	
173	  return profile as {
174	    id: string;
175	    display_name: string;
176	    timezone: string;
177	    phone_e164: string | null;
178	  };
179	}
180	
181	// ---------------------------------------------------------------------------
182	// Stable UUIDs from a seed namespace
183	// ---------------------------------------------------------------------------
184	
185	function seedUuid(userId: string, label: string): string {
186	  const input = `orma:seed:${userId}:${label}`;
187	  const encoder = new TextEncoder();
188	  const data = encoder.encode(input);
189	
190	  let h1 = 0x811c9dc5 >>> 0;
191	  let h2 = 0x6c62272e >>> 0;
192	  let h3 = 0x01000193 >>> 0;
193	  let h4 = 0xdeadbeef >>> 0;
194	  for (const b of data) {
195	    h1 = Math.imul(h1 ^ b, 0x01000193) >>> 0;
196	    h2 = Math.imul(h2 ^ b, 0x01000193) >>> 0;
197	    h3 = Math.imul(h3 ^ b, 0x0100019d) >>> 0;
198	    h4 = Math.imul(h4 ^ b, 0x010001a3) >>> 0;
199	  }
200	
201	  const raw = [h1, h2, h3, h4]
202	    .map((n) => (n >>> 0).toString(16).padStart(8, "0"))
203	    .join("");
204	
205	  const chars = raw.split("");
206	  chars[12] = "4";
207	  const variantNibble = (parseInt(chars[16], 16) & 0x3) | 0x8;
208	  chars[16] = variantNibble.toString(16);
209	
210	  const hex = chars.join("");
211	  return [
212	    hex.slice(0, 8),
213	    hex.slice(8, 12),
214	    hex.slice(12, 16),
215	    hex.slice(16, 20),
216	    hex.slice(20, 32),
217	  ].join("-");
218	}
219	
220	// ---------------------------------------------------------------------------
221	// Date helpers
222	// ---------------------------------------------------------------------------
223	
224	function todayInTimezone(tz: string): string {
225	  const now = new Date();
226	  const parts = new Intl.DateTimeFormat("en-CA", {
227	    timeZone: tz,
228	    year: "numeric",
229	    month: "2-digit",
230	    day: "2-digit",
231	  }).format(now);
232	  return parts;
233	}
234	
235	function subtractDays(dateStr: string, days: number): string {
236	  const d = new Date(dateStr + "T12:00:00Z");
237	  d.setUTCDate(d.getUTCDate() - days);
238	  return d.toISOString().slice(0, 10);
239	}
240	
241	function dateTimeInTz(
242	  dateStr: string,
243	  hour: number,
244	  minute: number,
245	  tz: string,
246	): string {
247	  const probe = new Date(`${dateStr}T${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}:00`);
248	  const utcStr = probe.toLocaleString("en-US", { timeZone: "UTC" });
249	  const tzStr = probe.toLocaleString("en-US", { timeZone: tz });
250	  const utcDate = new Date(utcStr);
251	  const tzDate = new Date(tzStr);
252	  const offsetMs = utcDate.getTime() - tzDate.getTime();
253	  const result = new Date(probe.getTime() + offsetMs);
254	  return result.toISOString();
255	}
256	
257	// ---------------------------------------------------------------------------
258	// CALL-E schema and request helpers
259	// ---------------------------------------------------------------------------
260	
261	const CALL_E_RESULT_SCHEMA = {
262	  type: "object",
263	  additionalProperties: false,
264	  required: ["captured_items", "retired_items"],
265	  properties: {
266	    captured_items: {
267	      type: "array",
268	      description: "New things the caller said they need to track. Empty array if none.",
269	      items: {
270	        type: "object",
271	        additionalProperties: false,
272	        required: ["text", "evidence_offset_seconds"],
273	        properties: {
274	          text: { type: "string", description: "The item in the caller's own words, one short line." },
275	          evidence_offset_seconds: { type: "integer", description: "Transcript offset in seconds where the caller said it." },
276	        },
277	      },
278	    },
279	    retired_items: {
280	      type: "array",
281	      description: "Items the caller asked to drop. Evidence is required because retiring is destructive. Empty array if none.",
282	      items: {
283	        type: "object",
284	        additionalProperties: false,
285	        required: ["item_id", "evidence_offset_seconds"],
286	        properties: {
287	          item_id: { type: "string", description: "The id given in the task for that item." },
288	          evidence_offset_seconds: { type: "integer", description: "Transcript offset in seconds where the caller asked to drop it." },
289	        },
290	      },
291	    },
292	    commitments: {
293	      type: "array",
294	      description: "Things the caller said out loud they would do, with a time attached where they gave one.",
295	      items: {
296	        type: "object",
297	        additionalProperties: false,
298	        required: ["item_id", "evidence_offset_seconds"],
299	        properties: {
300	          item_id: { type: "string", description: "The id given in the task for that item." },
301	          due: { type: "string", description: "When they said they would do it, in their own words. Omit if they gave no time." },
302	          evidence_offset_seconds: { type: "integer", description: "Transcript offset in seconds where they committed." },
303	        },
304	      },
305	    },
306	    slot_change_requested: {
307	      type: "string",
308	      enum: ["yes", "no", "unknown"],
309	      description: "Whether the caller asked to change their daily check-in time.",
310	    },
311	    slot_change_time: {
312	      type: "string",
313	      description: "The time they asked for, if any.",
314	    },
315	    mood: {
316	      type: "string",
317	      enum: ["ok", "low", "stressed", "energised", "unknown"],
318	      description: "How the caller sounded during the call.",
319	    },
320	  },
321	};
322	
323	function renderCallTask(briefing: SeedBriefing): string {
324	  return `You are Orma, calling ${briefing.user_name} for their daily two-minute check-in.
325	Both of you know you are a machine. Do not pretend otherwise, and do not apologise for it.
326	
327	Open with what they do not know, then move on:
328	${briefing.lead_line}
329	
330	Then walk what is open, briefly, not the whole list. These are the open items and their ids:
331	${briefing.open_items}
332	
333	After that, ask what is new and needs capturing. Never ask this first.
334	
335	Then offer the exit. Ask whether anything on the list should be dropped. If they want to drop
336	something, agree cleanly. Do not argue, do not ask them to reconsider, and do not make them
337	justify it.
338	
339	Close by confirming tomorrow at ${briefing.slot_local_time} and hang up. Target two minutes. Do not state any number
340	that was not given to you above.`;
341	}
342	
343	function maskPhoneNumber(phone: string): string {
344	  if (phone.length <= 7) return "X".repeat(phone.length);
345	  return `${phone.slice(0, 7)}${"X".repeat(phone.length - 7)}`;
346	}
347	
348	function buildMaskedRequestBody(
349	  callRunId: string,
350	  phone: string,
351	  task: string,
352	): string {
353	  return JSON.stringify({
354	    task,
355	    recipients: [
356	      {
357	        phones: [maskPhoneNumber(phone)],
358	      },
359	    ],
360	    result_schema: CALL_E_RESULT_SCHEMA,
361	    webhook_url: "https://orma-api.nryn.dev/functions/v1/calle-webhook/<redacted>",
362	    metadata: {
363	      call_run_id: callRunId,
364	    },
365	  });
366	}
367	
368	// ---------------------------------------------------------------------------
369	// Seed data definitions
370	// ---------------------------------------------------------------------------
371	
372	interface SeedMention {
373	  runIndex: number;
374	  offsetSeconds: number;
375	}
376	
377	interface SeedItem {
378	  id: string;
379	  text: string;
380	  sinceDateDaysAgo: number;
381	  source: string;
382	  mentions: SeedMention[];
383	}
384	
385	interface SeedBriefing {
386	  user_name: string;
387	  open_count: number;
388	  lead_line: string;
389	  open_items: string;
390	  last_call_summary: string;
391	  slot_local_time: string;
392	}
393	
394	interface SeedRun {
395	  id: string;
396	  idempotencyKey: string;
397	  localDate: string;
398	  daysAgo: number;
399	  partOfDay: string;
400	  scheduledHour: number;
401	  mood: string;
402	  briefing: SeedBriefing;
403	  transcript: Array<{ speaker: string; offset_seconds: number; text: string }>;
404	  structuredResult: {
405	    captured_items: Array<{ text: string; evidence_offset_seconds: number }>;
406	    retired_items: Array<{ item_id: string; evidence_offset_seconds: number }>;
407	    commitments: Array<{ item_id: string; evidence_offset_seconds: number }>;
408	    mood: string;
409	    slot_change_requested: string;
410	  };
411	}
412	
413	interface SeedPlan {
414	  profile: {
415	    id: string;
416	    display_name: string;
417	    timezone: string;
418	    phone_e164: string | null;
419	  };
420	  demoDate: string;
421	  items: SeedItem[];
422	  runs: SeedRun[];
423	}
424	
425	function buildPlan(
426	  profile: {
427	    id: string;
428	    display_name: string;
429	    timezone: string;
430	    phone_e164: string | null;
431	  },
432	  demoDate: string,
433	): SeedPlan {
434	  const userId = profile.id;
435	
436	  const dentistId = seedUuid(userId, "item:the-dentist");
437	  const passportId = seedUuid(userId, "item:renew-passport");
438	  const groceriesId = seedUuid(userId, "item:weekend-groceries");
439	
440	  const run1Id = seedUuid(userId, "run:1");
441	  const run2Id = seedUuid(userId, "run:2");
442	  const run3Id = seedUuid(userId, "run:3");
443	
444	  // All 3 runs fall in the 7-day window ending yesterday [demoDate - 7, demoDate - 1]
445	  // so compute_pattern_facts observes 3 days and generates weekly patterns.
446	  const run1Date = subtractDays(demoDate, 6);
447	  const run2Date = subtractDays(demoDate, 4);
448	  const run3Date = subtractDays(demoDate, 3);
449	
450	  return {
451	    profile,
452	    demoDate,
453	    items: [
454	      {
455	        id: dentistId,
456	        text: "the dentist",
457	        sinceDateDaysAgo: 34,
458	        source: "call",
459	        mentions: [
460	          { runIndex: 0, offsetSeconds: 0 },
461	          { runIndex: 1, offsetSeconds: 0 },
462	          { runIndex: 2, offsetSeconds: 0 },
463	        ],
464	      },
465	      {
466	        id: passportId,
467	        text: "renew the passport",
468	        sinceDateDaysAgo: 21,
469	        source: "telegram",
470	        mentions: [
471	          { runIndex: 1, offsetSeconds: 10 },
472	        ],
473	      },
474	      {
475	        id: groceriesId,
476	        text: "weekend groceries",
477	        sinceDateDaysAgo: 3,
478	        source: "call",
479	        mentions: [
480	          { runIndex: 2, offsetSeconds: 14 },
481	        ],
482	      },
483	    ],
484	    runs: [
485	      {
486	        id: run1Id,
487	        idempotencyKey: `orma:seed:${userId}:${run1Date}:morning:v1`,
488	        localDate: run1Date,
489	        daysAgo: 6,
490	        partOfDay: "morning",
491	        scheduledHour: 8,
492	        mood: "ok",
493	        briefing: {
494	          user_name: profile.display_name,
495	          open_count: 2,
496	          lead_line: "Everything open is still current.",
497	          open_items: `- the dentist (id: ${dentistId})\n- renew the passport (id: ${passportId})`,
498	          last_call_summary: "",
499	          slot_local_time: "08:00",
500	        },
501	        transcript: [
502	          { speaker: "bot", offset_seconds: 0, text: `Good morning, ${profile.display_name}. You\u2019ve had the dentist on your list for a while now.` },
503	          { speaker: "user", offset_seconds: 8, text: "Yeah, I know. I keep putting it off." },
504	          { speaker: "bot", offset_seconds: 12, text: "Anything new today?" },
505	          { speaker: "user", offset_seconds: 16, text: "No, nothing new." },
506	          { speaker: "bot", offset_seconds: 18, text: "Talk tomorrow at 8. Bye." },
507	        ],
508	        structuredResult: {
509	          captured_items: [],
510	          retired_items: [],
511	          commitments: [],
512	          mood: "ok",
513	          slot_change_requested: "no",
514	        },
515	      },
516	      {
517	        id: run2Id,
518	        idempotencyKey: `orma:seed:${userId}:${run2Date}:morning:v1`,
519	        localDate: run2Date,
520	        daysAgo: 4,
521	        partOfDay: "morning",
522	        scheduledHour: 8,
523	        mood: "ok",
524	        briefing: {
525	          user_name: profile.display_name,
526	          open_count: 2,
527	          lead_line: "Everything open is still current.",
528	          open_items: `- the dentist (id: ${dentistId})\n- renew the passport (id: ${passportId})`,
529	          last_call_summary: "Last call added nothing new.",
530	          slot_local_time: "08:00",
531	        },
532	        transcript: [
533	          { speaker: "bot", offset_seconds: 0, text: `Hi ${profile.display_name}. The dentist keeps coming up.` },
534	          { speaker: "user", offset_seconds: 6, text: "I will sort it this week." },
535	          { speaker: "bot", offset_seconds: 10, text: "You also have renew the passport open." },
536	          { speaker: "user", offset_seconds: 14, text: "That can wait a bit." },
537	          { speaker: "bot", offset_seconds: 18, text: "Noted. See you tomorrow." },
538	        ],
539	        structuredResult: {
540	          captured_items: [],
541	          retired_items: [],
542	          commitments: [],
543	          mood: "ok",
544	          slot_change_requested: "no",
545	        },
546	      },
547	      {
548	        id: run3Id,
549	        idempotencyKey: `orma:seed:${userId}:${run3Date}:morning:v1`,
550	        localDate: run3Date,
551	        daysAgo: 3,
552	        partOfDay: "morning",
553	        scheduledHour: 8,
554	        mood: "unknown",
555	        briefing: {
556	          user_name: profile.display_name,
557	          open_count: 2,
558	          lead_line: "You've mentioned the dentist 3 times. It's been 31 days.",
559	          open_items: `- the dentist (id: ${dentistId})\n- renew the passport (id: ${passportId})`,
560	          last_call_summary: "Last call added nothing new.",
561	          slot_local_time: "08:00",
562	        },
563	        transcript: [
564	          { speaker: "bot", offset_seconds: 0, text: `You\u2019ve mentioned the dentist three times. It\u2019s been ${34 - 3} days.` },
565	          { speaker: "user", offset_seconds: 7, text: "Fine, I will book it." },
566	          { speaker: "bot", offset_seconds: 10, text: "Need to pick up anything this weekend?" },
567	          { speaker: "user", offset_seconds: 14, text: "Yes, weekend groceries." },
568	          { speaker: "bot", offset_seconds: 17, text: "Got it. Talk tomorrow." },
569	        ],
570	        structuredResult: {
571	          captured_items: [
572	            { text: "weekend groceries", evidence_offset_seconds: 14 },
573	          ],
574	          retired_items: [],
575	          commitments: [],
576	          mood: "unknown",
577	          slot_change_requested: "no",
578	        },
579	      },
580	    ],
